writing.exampleCode:
use std::fmt;
struct Bytes(Vec<u8>);
impl fmt::Display for Bytes {
    fn fmt(&self, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(out, "{} bytes", self.0.len())
    }
}
fn main() {
    assert_eq!(Bytes(vec![1, 2, 3]).to_string(), "3 bytes");
}

